package config

import (
	"testing"

	. "github.com/future-architect/vuls/constant"
)

func TestSyslogConfValidate(t *testing.T) {
	var tests = []struct {
		conf              SyslogConf
		expectedErrLength int
	}{
		{
			conf:              SyslogConf{},
			expectedErrLength: 0,
		},
		{
			conf: SyslogConf{
				Protocol: "tcp",
				Port:     "5140",
			},
			expectedErrLength: 0,
		},
		{
			conf: SyslogConf{
				Protocol: "udp",
				Port:     "12345",
				Severity: "emerg",
				Facility: "user",
			},
			expectedErrLength: 0,
		},
		{
			conf: SyslogConf{
				Protocol: "foo",
				Port:     "514",
			},
			expectedErrLength: 1,
		},
		{
			conf: SyslogConf{
				Protocol: "invalid",
				Port:     "-1",
			},
			expectedErrLength: 2,
		},
		{
			conf: SyslogConf{
				Protocol: "invalid",
				Port:     "invalid",
				Severity: "invalid",
				Facility: "invalid",
			},
			expectedErrLength: 4,
		},
	}

	for i, tt := range tests {
		tt.conf.Enabled = true
		errs := tt.conf.Validate()
		if len(errs) != tt.expectedErrLength {
			t.Errorf("test: %d, expected %d, actual %d", i, tt.expectedErrLength, len(errs))
		}
	}
}

func TestDistro_MajorVersion(t *testing.T) {
	var tests = []struct {
		in  Distro
		out int
	}{
		{
			in: Distro{
				Family:  Amazon,
				Release: "2022 (Amazon Linux)",
			},
			out: 2022,
		},
		{
			in: Distro{
				Family:  Amazon,
				Release: "2 (2017.12)",
			},
			out: 2,
		},
		{
			in: Distro{
				Family:  Amazon,
				Release: "2017.12",
			},
			out: 1,
		},
		{
			in: Distro{
				Family:  CentOS,
				Release: "7.10",
			},
			out: 7,
		},
	}

	for i, tt := range tests {
		ver, err := tt.in.MajorVersion()
		if err != nil {
			t.Errorf("[%d] err occurred: %s", i, err)
		}
		if tt.out != ver {
			t.Errorf("[%d] expected %d, actual %d", i, tt.out, ver)
		}
	}
}

//go:build !windows

package syslog

import "testing"

func TestValidate(t *testing.T) {
	tests := []struct {
		name string
		conf Conf
		want int
	}{
		{"disabled", Conf{Protocol: "bad", Port: "bad", Severity: "bad", Facility: "bad"}, 0},
		{"defaults", Conf{Enabled: true}, 0},
		{"valid", Conf{Enabled: true, Protocol: "udp", Host: "localhost", Port: "514", Severity: "info", Facility: "auth"}, 0},
		{"all invalid", Conf{Enabled: true, Protocol: "bad", Port: "bad", Severity: "bad", Facility: "bad"}, 4},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := len(tt.conf.Validate()); got != tt.want {
				t.Errorf("Validate() returned %d errors, want %d", got, tt.want)
			}
		})
	}
}
//go:build windows

package syslog

import "testing"

func TestValidate(t *testing.T) {
	if got := (&Conf{}).Validate(); got != nil {
		t.Fatalf("disabled syslog: got %v, want nil", got)
	}
	err := (&Conf{Enabled: true}).Validate()
	if len(err) != 1 || err[0].Error() != "windows not support syslog" {
		t.Fatalf("enabled syslog: got %v, want one Windows error", err)
	}
}

package syslog

// Conf is syslog configuration.
type Conf struct {
	Protocol string `json:"-"`
	Host     string `valid:"host" json:"-"`
	Port     string `valid:"port" json:"-"`
	Severity string `json:"-"`
	Facility string `json:"-"`
	Tag      string `json:"-"`
	Verbose  bool   `json:"-"`
	Enabled  bool   `toml:"-" json:"-"`
}
//go:build windows

package syslog

import "golang.org/x/xerrors"

// Validate rejects syslog reporting on Windows.
func (c *Conf) Validate() []error {
	if !c.Enabled {
		return nil
	}
	return []error{xerrors.New("windows not support syslog")}
}

//go:build !windows

package syslog

import (
	"errors"
	"log/syslog"

	"github.com/asaskevich/govalidator"
	"golang.org/x/xerrors"
)

// Validate validates configuration
func (c *Conf) Validate() (errs []error) {
	if !c.Enabled {
		return nil
	}
	//  If protocol is empty, it will connect to the local syslog server.
	if len(c.Protocol) > 0 && c.Protocol != "tcp" && c.Protocol != "udp" {
		errs = append(errs, errors.New(`syslog.protocol must be "tcp" or "udp"`))
	}

	// Default port: 514
	if c.Port == "" {
		c.Port = "514"
	}

	if _, err := c.GetSeverity(); err != nil {
		errs = append(errs, err)
	}

	if _, err := c.GetFacility(); err != nil {
		errs = append(errs, err)
	}

	if _, err := govalidator.ValidateStruct(c); err != nil {
		errs = append(errs, err)
	}
	return errs
}

// GetSeverity gets severity
func (c *Conf) GetSeverity() (syslog.Priority, error) {
	if c.Severity == "" {
		return syslog.LOG_INFO, nil
	}

	switch c.Severity {
	case "emerg":
		return syslog.LOG_EMERG, nil
	case "alert":
		return syslog.LOG_ALERT, nil
	case "crit":
		return syslog.LOG_CRIT, nil
	case "err":
		return syslog.LOG_ERR, nil
	case "warning":
		return syslog.LOG_WARNING, nil
	case "notice":
		return syslog.LOG_NOTICE, nil
	case "info":
		return syslog.LOG_INFO, nil
	case "debug":
		return syslog.LOG_DEBUG, nil
	default:
		return -1, xerrors.Errorf("Invalid severity: %s", c.Severity)
	}
}

// GetFacility gets facility
func (c *Conf) GetFacility() (syslog.Priority, error) {
	if c.Facility == "" {
		return syslog.LOG_AUTH, nil
	}

	switch c.Facility {
	case "kern":
		return syslog.LOG_KERN, nil
	case "user":
		return syslog.LOG_USER, nil
	case "mail":
		return syslog.LOG_MAIL, nil
	case "daemon":
		return syslog.LOG_DAEMON, nil
	case "auth":
		return syslog.LOG_AUTH, nil
	case "syslog":
		return syslog.LOG_SYSLOG, nil
	case "lpr":
		return syslog.LOG_LPR, nil
	case "news":
		return syslog.LOG_NEWS, nil
	case "uucp":
		return syslog.LOG_UUCP, nil
	case "cron":
		return syslog.LOG_CRON, nil
	case "authpriv":
		return syslog.LOG_AUTHPRIV, nil
	case "ftp":
		return syslog.LOG_FTP, nil
	case "local0":
		return syslog.LOG_LOCAL0, nil
	case "local1":
		return syslog.LOG_LOCAL1, nil
	case "local2":
		return syslog.LOG_LOCAL2, nil
	case "local3":
		return syslog.LOG_LOCAL3, nil
	case "local4":
		return syslog.LOG_LOCAL4, nil
	case "local5":
		return syslog.LOG_LOCAL5, nil
	case "local6":
		return syslog.LOG_LOCAL6, nil
	case "local7":
		return syslog.LOG_LOCAL7, nil
	default:
		return -1, xerrors.Errorf("Invalid facility: %s", c.Facility)
	}
}

